// 鑰屾槸鐭殏杞绛夊緟瀹冨嚭鐜帮紙waitForFile锛夛紝涓€鏃﹁浆鐮佽繘搴﹁拷涓婂氨绔嬪嵆鍝嶅簲鈥斺€?








// 鐪熸鍋氬埌"闅忓嚭闅忔挱"锛岃€屼笉鏄鎾斁鍣ㄨ嚜宸遍噸璇曟垨鑰呭共绛夋暣棣栨瓕杞畬銆傚鏋滆繖









// 棣栨瓕鐨勮浆鐮佷换鍔℃湰韬凡缁忓け璐ワ紝鎴栬€呯瓑寰呭お涔呴兘娌＄瓑鍒帮紙姣斿婧愭枃浠舵崯鍧忋€佸崱鍦?








// 鏋佺鎯呭喌锛夛紝鎵嶄細鏄庣‘鍦版姤閿欒€屼笉鏄棤闄愭湡鎸傝捣璇锋眰銆?








app.get('/hls/:id/:file', async (req, res) => {









  const { id, file } = req.params;









  if (!/^\d+$/.test(id) || !/^[\w.-]+$/.test(file)) return res.status(400).end();









  const p = path.join(outDir(id), file);



















  let ready = fs.existsSync(p);









  if (!ready) {









    try {









      await waitForFile(p, id);









      ready = true;









    } catch (e) {









      if (e.code === 'BUILD_FAILED') {









        log.error('HLS', `鍒嗙墖鐢熸垚澶辫触: id=${id}, file=${file}: ${e.cause && e.cause.message}`);









        return res.status(500).end();









      }









      log.warn('HLS', `绛夊緟鍒嗙墖瓒呮椂: id=${id}, file=${file}`);









      return res.status(404).end(); // 绛夊緟瓒呮椂锛岃涓虹‘瀹炰笉瀛樺湪锛堜緥濡傞潪娉曟枃浠跺悕/宸茶娓呯悊锛?








    }









  }



















  if (file.endsWith('.m3u8')) res.set({ 'Content-Type': 'application/vnd.apple.mpegurl', 'Cache-Control': 'no-store' });









  else if (file.endsWith('.ts')) res.set({ 'Content-Type': 'video/mp2t', 'Cache-Control': 'public, max-age=31536000, immutable' });









  fs.createReadStream(p).pipe(res);









});



















