// 绌洪棿銆佺爜鐜囪繃楂樺鑷寸殑鍏煎鎬ч棶棰樼瓑)鍏跺疄鍙互鍦ㄦ湇鍔＄鎻愬墠鐢?ffprobe 鎺㈡祴鍑烘潵锛?








// 鎵撹繘鏃ュ織锛屾柟渚跨鐞嗗憳鎺掓煡"鏌愰姝屽湪纭В妯″紡涓嬫斁涓嶅嚭鏉?鍒板簳鏄笉鏄枃浠舵湰韬殑









// 闂銆俻robeCodecInfo 缁撴灉鎸夋瓕鏇?id 缂撳瓨锛岄伩鍏嶅悓涓€棣栨瓕琚弽澶嶈姹傛椂閲嶅鎺㈡祴銆?








const codecInfoCache = new Map(); // song_id -> { videoCodec, videoProfile, width, height, audioCodec, audioChannels, probedAt }



















async function probeCodecInfo(song, srcPath) {









  const cached = codecInfoCache.get(song.id);









  if (cached) return cached;









  try {









    const { stdout } = await execFileAsync('ffprobe', [









      '-v', 'error',









      '-show_entries', 'stream=codec_type,codec_name,profile,width,height,channels',









      '-of', 'json',









      srcPath || song.filepath,









    ], { timeout: 15000 });









    const info = JSON.parse(stdout);









    const v = (info.streams || []).find(s => s.codec_type === 'video') || {};









    const a = (info.streams || []).find(s => s.codec_type === 'audio') || {};









    const result = {









      videoCodec: v.codec_name || '鏈煡', videoProfile: v.profile || '鏈煡',









      width: v.width || 0, height: v.height || 0,









      audioCodec: a.codec_name || '鏈煡', audioChannels: a.channels || 0,









      probedAt: Date.now(),









    };









    codecInfoCache.set(song.id, result);









    return result;









  } catch (e) {









    log.warn('STREAM', `[姝屾洸 id=${song.id}] ffprobe 缂栬В鐮佷俊鎭帰娴嬪け璐ワ紝涓嶅奖鍝嶇洿杩炴挱鏀炬湰韬紝浠呯己灏戣瘖鏂俊鎭? ${e.message.split('\n')[0]}`);









    return null;









  }









}



















