app.get('/api/songs/newest', (req, res) => {









  const limit = Math.min(parseInt(req.query.limit, 10) || 50, 200);









  try {









    const rows = db.prepare('SELECT * FROM songs ORDER BY id DESC LIMIT ?').all(limit);









    res.json(rows);









  } catch (e) {









    console.error('[newest] error:', e.message);









    res.json([]);









  }









});



















