// 鎸?song_artists 鍏宠仈琛ㄥ垎缁勶紝鑰屼笉鏄洿鎺ュ songs.artist 鏁存瀛楃涓插垎缁勨€斺€?








// 杩欐牱"鍒€閮?寮犱笁"杩欑被鍚堝敱鏇茬洰浼氳鍒€閮庛€佸紶涓夊垎鍒嚭鐜板湪姝屾墜鍒楄〃閲屻€佸垎鍒鍏?








// 鍚勮嚜鐨勬洸鐩暟锛岃€屼笉鏄褰撴垚涓€涓鎬殑缁勫悎姝屾墜鍚嶆暣浣撳睍绀恒€?








// 鍒嗛〉鏀寔(闇€姹?姝屾墜鍒楄〃涔熸敮鎸佺湡姝ｇ殑鏈嶅姟绔垎椤碉紝鍜岀偣姝屽垪琛ㄥ姞杞介€昏緫鐩稿悓")锛?








// 璺?/api/songs 鍚屼竴濂楃害瀹氣€斺€斿彧鏈夎姹傛樉寮忓甫涓?page & pageSize 鏃舵墠璧板垎椤靛垎鏀紝









// 杩斿洖 { items, total, page, pageSize, totalPages } 甯﹀厓淇℃伅鐨勫璞★紱涓嶅甫鍒嗛〉









// 鍙傛暟鏃朵粛鐒跺拰浠ュ墠涓€鏍风洿鎺ヨ繑鍥炴暟缁?鎵嬫満绔?鑰佺増鏈鎴风杩樺湪鐢?锛屽畬鍏ㄥ悜鍚庡吋瀹广€?








app.get('/api/artists', (req, res) => {









  const pageRaw = parseInt(req.query.page, 10);









  const pageSizeRaw = parseInt(req.query.pageSize, 10);









  const paginate = Number.isInteger(pageRaw) && pageRaw > 0 && Number.isInteger(pageSizeRaw) && pageSizeRaw > 0;









  const page = paginate ? pageRaw : 1;









  const pageSize = paginate ? Math.min(pageSizeRaw, 500) : 0;



















  const rows = db.prepare(`









    SELECT artist, COUNT(*) as count









    FROM song_artists









    GROUP BY artist









    ORDER BY artist









  `).all();









  // 闄勫甫 hasAvatar 鏍囪锛屽墠绔嵁姝ゅ喅瀹氭覆鏌撳ご鍍忓浘鐗囪繕鏄瀛楀厹搴曪紝涓嶇敤鍐嶄负









  // 姣忎釜姝屾墜鍗曠嫭鍙戜竴娆¤姹傚幓鎺㈡祴澶村儚鏄惁瀛樺湪銆?








  const avatarMap = getSingerAvatarMap();









  const withAvatar = r => ({ ...r, hasAvatar: avatarMap.has(r.artist) });



















  if (!paginate) {









    return res.json(rows.map(withAvatar));









  }









  const total = rows.length;









  const totalPages = Math.max(1, Math.ceil(total / pageSize));









  const offset = (Math.min(page, totalPages) - 1) * pageSize;









  const items = rows.slice(offset, offset + pageSize).map(withAvatar);









  res.json({ items, total, page, pageSize, totalPages });









});



















