// scanner.js 鐨?yieldToEventLoop 鍚屾牱鐨勮€冭檻锛夛紝閬垮厤涓€娆℃€у嬀閫夊緢澶氶鏃堕暱鏃堕棿









// 闃诲鍏跺畠璇锋眰锛涘崟棣栨帰娴嬪け璐ワ紙姣斿鏂囦欢鎭板ソ琚Щ璧帮級鍙鏃ュ織璺宠繃锛屼笉褰卞搷









