function getRootsWithStatus() {









  return getLibraryRoots().map(r => ({









    ...r,









    accessible: fs.existsSync(r.dir),









    songCount: db.prepare('SELECT COUNT(*) c FROM songs WHERE source_root = ?').get(r.dir).c,









  }));









}



















