function triggerStrmProbeIfNeeded(song) {









  if (song.is_strm && song.audio_tracks == null) {









    ensureProbedOnDemand(song)









      .then((audio_tracks) => {









        log.info('STRM', `[姝屾洸 id=${song.id}] 瑙﹀彂鎸夐渶鎺㈡祴瀹屾垚锛岄煶杞ㄦ暟=${audio_tracks}`);









        broadcastQueue();









      })









      .catch(e => log.warn('STRM', `[姝屾洸 id=${song.id}] 瑙﹀彂鎸夐渶鎺㈡祴澶辫触: ${e.message}`));









  }









}



















