const micPing = setInterval(() => {









  wss.clients.forEach(ws => {









    if (ws._channel !== 'mic') return;









    if (ws.isAlive === false) { try { ws.terminate(); } catch (e) {} return; }









    ws.isAlive = false;









    try { ws.ping(); } catch (e) {}









  });









}, 30000);



















