        if (typeof p.stroke === 'string' && /^#[0-9a-fA-F]{6}$/.test(p.stroke)) msg.stroke = p.stroke;









        if (typeof p.width === 'number' && p.width >= 0 && p.width <= 12) msg.width = p.width;









